```sop
@slots literal
{"seats": {"A": 5, "B": 3, "C": 3}, "threshold": 6}

@answer jsEval
const names = Object.keys($slots.seats);
const subsets = [];
for (let mask = 1; mask < (1 << names.length); mask++) {
  const members = names.filter((_, index) => mask & (1 << index));
  subsets.push(members);
}
const sum = (members) => members.reduce((total, name) => total + $slots.seats[name], 0);
const isWinning = (members) => sum(members) >= $slots.threshold;
const minimal = subsets.filter((members) => {
  if (!isWinning(members)) return false;
  return members.every((name) => !isWinning(members.filter((m) => m !== name)));
});
const labels = minimal.map((members) => "{" + members.join(",") + "}");
return labels.join(", ") + " are the minimal winning coalitions.";
```

